use minmax_stack::MinMaxStack;

#[test]
fn test_push_and_pop() {
    let mut s = MinMaxStack::new();
    s.push(3);
    s.push(1);
    s.push(4);
    assert_eq!(s.pop(), Some(4));
    assert_eq!(s.pop(), Some(1));
    assert_eq!(s.pop(), Some(3));
    assert_eq!(s.pop(), None);
}

#[test]
fn test_get_min() {
    let mut s = MinMaxStack::new();
    s.push(5);
    s.push(2);
    s.push(8);
    assert_eq!(s.get_min(), Some(&2));
    s.pop(); // removes 8
    assert_eq!(s.get_min(), Some(&2));
    s.pop(); // removes 2
    assert_eq!(s.get_min(), Some(&5));
}

#[test]
fn test_get_max() {
    let mut s = MinMaxStack::new();
    s.push(3);
    s.push(7);
    s.push(1);
    assert_eq!(s.get_max(), Some(&7));
    s.pop(); // removes 1
    assert_eq!(s.get_max(), Some(&7));
    s.pop(); // removes 7
    assert_eq!(s.get_max(), Some(&3));
}

#[test]
fn test_empty_returns_none() {
    let s: MinMaxStack<i32> = MinMaxStack::new();
    assert_eq!(s.get_min(), None);
    assert_eq!(s.get_max(), None);
    assert_eq!(s.peek(), None);
}

#[test]
fn test_peek_does_not_consume() {
    let mut s = MinMaxStack::new();
    s.push(42);
    assert_eq!(s.peek(), Some(&42));
    assert_eq!(s.get_min(), Some(&42));
    assert!(!s.is_empty());
}

