Implement MinMaxStack in src/lib.rs.

pub struct MinMaxStack<T> {
    data:    Vec<T>,
    min_stk: Vec<T>,  // tracks running minimum
    max_stk: Vec<T>,  // tracks running maximum
}

impl<T: Ord + Clone> MinMaxStack<T> {
    pub fn new() -> Self
    pub fn push(&mut self, item: T)
        // Push to data. If min_stk is empty or item <= min_stk.last(), push to min_stk.
        // If max_stk is empty or item >= max_stk.last(), push to max_stk.
    pub fn pop(&mut self) -> Option<T>
        // Pop from data. If popped item == min_stk.last(), also pop from min_stk.
        // If popped item == max_stk.last(), also pop from max_stk.
    pub fn peek(&self) -> Option<&T>       // top of data
    pub fn get_min(&self) -> Option<&T>    // top of min_stk
    pub fn get_max(&self) -> Option<&T>    // top of max_stk
    pub fn is_empty(&self) -> bool
}

All 5 tests in tests/minmax_test.rs must pass.
